def find_peak(heights: list[int]) -> int:
    for i in range(len(heights) - 1):
        # The first step down: heights[i] beat its left side (or i == 0), because
        # the scan didn't stop at i - 1.
        if heights[i] > heights[i + 1]:
            return i
    return len(heights) - 1  # never stepped down: the last one is a peak

