fn find_peak(heights: Vec<i64>) -> usize {
    let (mut lo, mut hi) = (0, heights.len() - 1);
    // Invariant: some peak lies in [lo, hi].
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if heights[mid] < heights[mid + 1] {
            lo = mid + 1; // uphill to the right: a peak is further right
        } else {
            hi = mid; // downhill: mid itself or something left of it is a peak
        }
    }
    lo
}
